using Check=std::function<void(bool,const char*)>;
class ActivationBlock {HHOOK hook_=nullptr;public:ActivationBlock(){hook_=SetWindowsHookEx(WH_CBT,[](int code,WPARAM wp,LPARAM lp)->LRESULT{return code==HCBT_ACTIVATE?1:CallNextHookEx(nullptr,code,wp,lp);},nullptr,GetCurrentThreadId());if(!hook_)throw std::runtime_error("Cannot isolate cursor fixture");}~ActivationBlock(){UnhookWindowsHookEx(hook_);}};
std::vector<UINT> Primaries(const sct::services::Settings& settings){std::vector<UINT> result;for(const auto& family:sct::ui::GroupedHomeCommands(settings))result.push_back(family.primary.id);return result;}
void WriteFixture(const std::filesystem::path& file,const char* value){std::ofstream output(file,std::ios::binary);output<<value;if(!output)throw std::runtime_error("Cannot write default fixture");}
void Defaults(Check check,const std::filesystem::path& dir){
    using namespace sct;using namespace ui;services::Settings defaults,loaded;CString error;
    const UINT tool=EditorToolFirst;const std::vector<UINT> expected={NewDocument,SaveAs,Undo,tool+7,tool+3,tool+16,tool+6,tool+9,tool+4,Color,tool+8,PrintImage,CloseDocument,Copy,Properties,tool+5,tool+13,tool+20,tool+22,ResizeImage,Rotate90,Combine,Effects,ZoomFit,ShowThumbnails};
    check(defaults.editorHomeConfigured&&Primaries(defaults)==expected,"captured INI Home defaults preserve all25 real families and their exact current order without fixed More");
    check(defaults.hotkeys[0].key=='1'&&defaults.hotkeys[1].key=='X'&&defaults.hotkeys[1].modifiers==(MOD_CONTROL|MOD_SHIFT)&&defaults.hotkeys[6].key=='7'&&!defaults.hotkeys[7].key&&!defaults.hotkeys[12].key,"captured shortcut defaults include Ctrl+Shift+X and preserve all other enabled/disabled slots");
    const RECT expectedRegion{593,445,760,572};check(EqualRect(&defaults.lastRegion,&expectedRegion)!=FALSE,"captured last-region coordinates match the current INI baseline");
    check(defaults.directory==services::paths::DefaultCaptures()&&defaults.format==L"jpg"&&defaults.languageFile==L"lang_tw.ini"&&defaults.delay==0&&defaults.fixedWidth==800&&defaults.fixedHeight==600&&!defaults.cursor&&defaults.editAfter&&defaults.closeToTray&&!defaults.saveAfter&&!defaults.copyAfter&&!defaults.clientOnly&&!defaults.childWindow&&defaults.jpegQuality==90&&defaults.captureMagnifier&&defaults.captureGrid&&defaults.dimOutside&&defaults.hideEditors&&defaults.scrollDelay==350&&defaults.filePattern==L"capture_{date}_{time}_{ms}_{counter}"&&defaults.presets.empty()&&!defaults.homeFeaturesConfigured&&!defaults.editorHomeChildrenConfigured&&defaults.toolStyles.IsEmpty(),"all other captured scalar/interface settings match while the capture directory stays portable and image saves stay explicit");
    CString name;name.Format(L"missing-%lu-%llu.ini",GetCurrentProcessId(),GetTickCount64());const auto missing=dir/name.GetString();services::ConfigService config(missing.c_str());check(!std::filesystem::exists(missing)&&config.Load(loaded,error)&&loaded.editorHome==defaults.editorHome&&loaded.hotkeys[1].key=='X'&&EqualRect(&loaded.lastRegion,&defaults.lastRegion),"first-run missing INI is generated from the captured default baseline");
    services::Settings fallback;fallback.editorHomeConfigured=false;check(Primaries(fallback)==expected,"missing legacy Home field and explicit default restoration share the same captured baseline");
    WriteFixture(dir/L"partial.ini","[Capture]\nFormat=png\n[ScreenshotOptions]\nImageSavePolicy=1\n");services::ConfigService partial((dir/L"partial.ini").c_str());check(partial.Load(loaded,error)&&loaded.format==L"png"&&loaded.editorHome==defaults.editorHome&&loaded.hotkeys[1].key=='X',"partial INI inherits new defaults without replacing explicitly supplied settings");
    auto custom=defaults;custom.editorHome=L"Color,SaveAs";custom.editorHomeChildrenConfigured=true;custom.editorHomeChildren=L"ScreenColor,SaveAs";custom.hotkeys[1].key='Z';custom.lastRegion={1,2,30,40};check(config.Save(custom,error)&&config.Load(loaded,error)&&loaded.editorHome==custom.editorHome&&loaded.editorHomeChildren==custom.editorHomeChildren&&loaded.hotkeys[1].key=='Z'&&EqualRect(&loaded.lastRegion,&custom.lastRegion),"existing custom Home, child preferences, hotkey and region always override defaults");
    custom.editorHome.Empty();custom.editorHomeChildren.Empty();check(config.Save(custom,error)&&config.Load(loaded,error)&&Primaries(loaded).empty(),"existing explicit empty Home remains empty instead of reapplying defaults");
}
